import{culinaryEngine}from"../../js-modules/culinary-engine.js";import{INGREDIENTS}from"../../js-modules/culinary-data.js";function initPantry(){const e=document.getElementById("ui-pantry");e.innerHTML="";for(const[t,n]of Object.entries(INGREDIENTS)){const i=document.createElement("button");i.className="ing-btn",i.innerHTML=`\n            <span class="ing-icon">${n}</span>\n            <span class="ing-name">${t}</span>\n        `,i.addEventListener("click",()=>{culinaryEngine.selectIngredient(t)}),e.appendChild(i)}}function updateHUD(e){document.getElementById("ui-score").textContent=e.score,document.getElementById("ui-coins").textContent=e.coins,document.getElementById("ui-xp").textContent=e.xp,document.getElementById("ui-multiplier").textContent=`x${e.multiplier}`;const t=document.getElementById("ui-message");t.textContent=e.resultMessage,e.resultMessage&&!e.gameOver&&setTimeout(()=>{t.textContent===e.resultMessage&&(t.textContent="",e.resultMessage="")},3e3)}function updateTicket(e){const t=e.currentOrder;if(!t)return;document.getElementById("ui-recipe-name").textContent=t.name,document.getElementById("ui-time-text").textContent=e.timeLeft;const n=e.timeLeft/e.maxTime*100,i=document.getElementById("ui-timer-bar");i.style.width=`${n}%`,i.style.backgroundColor=n<30?"#ef4444":"#10b981";const s=document.getElementById("ui-recipe-reqs");s.innerHTML="",t.ingredients.forEach((t,n)=>{const i=n<e.selectedIngredients.length,d=document.createElement("div");d.className="req-item "+(i?"done":""),d.innerHTML=`<span class="req-box"></span> ${t}`,s.appendChild(d)})}function checkModal(e){e.gameOver&&(document.getElementById("result-modal").classList.remove("hidden"),document.getElementById("modal-result-msg").textContent=e.resultMessage)}document.addEventListener("DOMContentLoaded",()=>{initPantry(),culinaryEngine.subscribe(e=>{updateHUD(e),updateTicket(e),checkModal(e)}),document.getElementById("btn-next-order").addEventListener("click",()=>{document.getElementById("result-modal").classList.add("hidden"),culinaryEngine.nextOrder()}),updateHUD(culinaryEngine.state),updateTicket(culinaryEngine.state)});